"""Enclose the signed normalized head using brackets generated by loc.py."""

from collections import defaultdict
from pathlib import Path

from flint import arb, ctx

ctx.prec = 100
pi = arb.pi()
a = arb(2).log() / 4
dt = pi / 128
idx = list(map(int, Path(__file__).with_name("idx").read_text().split()))
assert len(idx) == 298 and idx == sorted(set(idx)) and 1 < idx[0] <= idx[-1] <= 11001
assert idx[-1] * dt < 271

# P_k(u,v) in (d/du)^k exp(-v) = P_k(u,v) exp(-v), v = 1/(1-u^2).
polys = [{(0, 0): 1}]
for k in range(4):
    p = defaultdict(int)
    for (i, j), c in polys[-1].items():
        if i:
            p[i - 1, j] += i * c
        if j:
            p[i + 1, j + 1] += 2 * j * c
        p[i + 1, j + 2] -= 2 * c
    polys.append(p)

# Enclose numerical upper bounds on the L1 norms, not the norms themselves.
orders = (0, 1, 2, 4)
norm = [arb(0) for _ in range(5)]
D = 16384
cut = D - D // 256
for l in range(cut):
    u = arb(2 * l + 1, 1) / (2 * D)
    v = 1 / (1 - u * u)
    ev = (-v).exp()
    for k in orders:
        p = sum(c * u**i * v**j for (i, j), c in polys[k].items())
        norm[k] += abs(p * ev).upper() / D
for k in orders:
    assert max(j for i, j in polys[k]) <= 8
    norm[k] += sum(abs(c) * 128**j for (i, j), c in polys[k].items()) * arb(-128).exp() / 256
    norm[k] *= 2 * a ** (1 - k)
for k, bound in zip(orders, ("0.076943", "0.736100", "18.481922", "226358.366")):
    assert norm[k] < arb(bound)

M = norm[0] + (arb(1) / 900 + arb(1) / 1600) * norm[2] + norm[4] / 1440000
assert M < arb("0.26623")


def log_derivative(A):
    s = arb(A) + arb("0.5")
    # 2 sum_{n>=2} n^(1-s), bounded by its first term and an integral.
    assert 2 * (arb(2) ** (1 - s) + arb(2) ** (2 - s) / (s - 2)) < arb("1e-8")
    return (s + 2).digamma() - pi.log() + arb(0, "1e-8")


def weight(t):
    return 1 / ((1 + t * t / 900) * (1 + t * t / 1600))


Wtotal = (log_derivative(30) / 30 - log_derivative(40) / 40) * 1440000 / 700
# The residual expression bounds omitted weight from above: subtract only
# the lower weight of each chosen zero at its outer bracket endpoint.
res = Wtotal - 2 * sum(weight(j * dt) for j in idx)
assert 0 < res and res < arb("0.08577")
omitted = res * M
assert omitted < arb("0.02284")
print("total weight, residual upper-bound expression, M, omitted budget:", Wtotal, res, M, omitted)

# Composite trapezoid at bracket midpoints, with the factor two for both
# signs. Endpoints of the bump vanish. Evaluate the trig arguments directly.
N = 4096
dx = 2 * a / N
bt = [(-1 / (1 - (arb(2 * l - N) / N) ** 2)).exp() * dx for l in range(1, N)]
mid_sum = arb(0)
location = arb(0)
quadrature = arb(0)
for j in idx:
    t = (arb(j) - arb("0.5")) * dt
    step, start = dx * t, a * t
    mid_sum += 2 * sum(b * (start + l * step).cos() for l, b in enumerate(bt, 1))
    der0 = 3 * a * norm[0]
    der2 = (2 * norm[1] + 3 * a * norm[2]) / ((j - 1) * dt) ** 2
    location += dt * der0.min(der2)
    quadrature += dx**2 / 4 * (norm[2] + 2 * t * norm[1] + t * t * norm[0])
assert arb("-0.118966") < mid_sum and mid_sum < arb("-0.118964")
assert location < arb("0.01659") and quadrature < arb("0.00132")
print("signed midpoint sum, location budget, quadrature budget:", mid_sum, location, quadrature)

error = location + quadrature + omitted
assert mid_sum - error > arb("-0.160") and mid_sum + error < arb("-0.078")
center, eps, lean_tail = arb("-0.118965"), arb("0.040751"), arb(425984) / 10**12
assert abs(mid_sum - center) + error < eps
assert abs(center) - eps - lean_tail > arb("0.078")
print("certified normalized head and full capped sum: (-0.160, -0.078)")
